// Gemini wrapper. Every call is logged and its token usage/cost recorded automatically.
import { GoogleGenerativeAI } from '@google/generative-ai';
import { log, withLogging } from '../utils/logger.js';
import { computeCost } from '../utils/costTracker.js';

export const DEFAULT_MODEL = process.env.GEMINI_MODEL || 'gemini-2.5-flash';

let client;
function getClient() {
  if (!process.env.GEMINI_API_KEY) throw new Error('GEMINI_API_KEY is not set');
  client ??= new GoogleGenerativeAI(process.env.GEMINI_API_KEY);
  return client;
}

/**
 * @param {string} prompt
 * @param {{ model?: string, system?: string, tracker?: import('../utils/costTracker.js').CostTracker }} opts
 * @returns {Promise<{ text: string, usage: object }>}
 */
async function generateRaw(prompt, { model = DEFAULT_MODEL, system, tracker } = {}) {
  const m = getClient().getGenerativeModel({ model, systemInstruction: system });
  const res = await m.generateContent(prompt);
  const meta = res.response.usageMetadata ?? {};
  const input = meta.promptTokenCount ?? 0;
  const output = meta.candidatesTokenCount ?? 0;
  const usage = tracker ? tracker.add(model, input, output) : computeCost(model, input, output);
  log('llm.usage', { model, ...usage });
  return { text: res.response.text(), usage };
}

export const generate = withLogging('llm', 'gemini.generate', (prompt, opts = {}) =>
  // Drop the tracker from logged args — it's not serializable context.
  generateRaw(prompt, opts),
);

