// Page content extraction via Tavily /extract. Logged automatically.
import { withLogging } from '../utils/logger.js';
import { tavilyPost } from './tavily.js';

/**
 * @param {string} url
 * @returns {Promise<{ url: string, content: string }>}
 */
async function fetchPage(url) {
  const data = await tavilyPost('/extract', { urls: [url] });
  const page = data.results?.[0];
  if (!page) throw new Error(`Tavily could not extract ${url}`);
  return { url: page.url, content: page.raw_content };
}

export const pageFetch = withLogging('tool', 'pageFetch', fetchPage, {
  // Full page text is large; log length + preview, the caller still gets everything.
  summarize: (r) => ({ url: r.url, length: r.content.length, preview: r.content.slice(0, 300) }),
});

