96	async function synthesize(ctx, question, planResult, sources) {
97	  const evidence = sources
98	    .map((s, i) => `[S${i + 1}] ${s.title}\nURL: ${s.url}\n${s.content.slice(0, MAX_SOURCE_CHARS)}`)
99	    .join('\n\n');
100	
101	  return askJson(ctx, `Answer the research question using ONLY the evidence below.
102	Rules:
103	- Every claim must be directly stated by a source. "citedUrl" is the URL of the best source for it; "supportingUrls" lists EVERY source URL that states it (including citedUrl).
104	- If the evidence does not answer something the question asks, put it in "unableToFind". Never fill gaps from your own knowledge and never guess.
105	- "entitiesLearned": named entities with facts established by the evidence, as {"name", "type", "data": {key facts}}.
106	- "answer" summarises only what the claims support.
107	
108	Return JSON exactly in this shape:
109	{"answer": string, "claims": [{"text": string, "citedUrl": string, "supportingUrls": string[]}], "entitiesLearned": [{"name": string, "type": string, "data": object}], "unableToFind": string[]}
110	
111	Question: ${question}
112	Sub-questions to cover:
113	${planResult.subQuestions.map((q) => `- ${q}`).join('\n')}
114	
115	Evidence:
116	${evidence}`);
117	}
118	
119	// Claims backed by one domain get a targeted search for a second, independent source.
120	// Corroboration is a keyword-overlap heuristic, not semantic verification — the auditor's job.
121	export async function crossCheck(ctx, claims) {
122	  const single = [];
123	  for (const claim of claims) {
124	    if (claim.citedUrl.startsWith('memory:')) {
125	      claim.corroboration = 'memory';
126	      continue;
127	    }
128	    const domains = new Set([claim.citedUrl, ...(claim.supportingUrls ?? [])].map(domainOf));
129	    if (domains.size > 1) {
130	      claim.corroboration = 'multi_source';
131	      continue;
132	    }
133	    claim.corroboration = 'single_source';
134	    const action = single.length < MAX_CROSS_CHECKS ? 'targeted_search' : 'skipped_cap_reached';
135	    trace(ctx, 'decision', { decision: 'single_source_claim_detected', claim: claim.text, citedUrl: claim.citedUrl, action });
136	    if (action === 'targeted_search') single.push(claim);
137	  }
138	  if (!single.length) return;
139	
140	  const batch = await searchAll(ctx, single.map((c) => c.text.slice(0, 200)), 'cross_check');
141	  single.forEach((claim, i) => {
142	    const terms = keyTerms(claim.text);
