input.command:
cat > "$TMP/scan.cjs" <<'EOF'
const fs = require('fs');
const file = process.argv[2];
const text = fs.readFileSync(file, 'utf8');
const mask = (s) => `${s.slice(0, 5)}…(${s.length} chars)`;
const envVals = fs.readFileSync('.env', 'utf8').split(/\r?\n/)
  .map((l) => l.match(/^([A-Z_]*(KEY|TOKEN|SECRET)[A-Z_]*)=(.+)$/)).filter(Boolean)
  .map((m) => ({ name: m[1], value: m[3].trim().replace(/^["']|["']$/g, '') })).filter((e) => e.value.length >= 8);
for (const e of envVals) console.log(`.env ${e.name}: ${text.split(e.value).length - 1} occurrence(s) in copy`);
const patterns = {
  gemini: /AIza[0-9A-Za-z_\-]{35}/g,
  tavily: /tvly-[A-Za-z0-9_\-]{16,}/g,
  openai_anthropic: /sk-(?:ant-)?[A-Za-z0-9_\-]{20,}/g,
  github: /gh[pousr]_[A-Za-z0-9]{30,}/g,
  aws: /AKIA[0-9A-Z]{16}/g,
  bearer: /Bearer\s+[A-Za-z0-9._\-]{20,}/g,
  assigned: /(?:API_KEY|_KEY|SECRET|TOKEN|PASSWORD)["']?\s*[=:]\s*["']?[A-Za-z0-9._\-]{16,}/gi,
};
for (const [name, re] of Object.entries(patterns)) {
  const hits = [...new Set(text.match(re) ?? [])];
  console.log(`${name}: ${hits.length} distinct`, hits.slice(0, 8).map(mask));
}
EOF
node "$TMP/scan.cjs" logs/claude-sessions/4e424236-76bc-49f5-86cc-7e0bb60dfefb.jsonl

